namespace ghidra.app.plugin.core.compositeeditor;

using docking;
using ghidra.util.exception;

public class EditBitFieldAction : CompositeEditorTableAction {

	public static string ACTION_NAME = "Edit Bitfield";
	private static string GROUP_NAME = BITFIELD_ACTION_GROUP;
	private static string DESCRIPTION = "Edit an existing bitfield";
	private static string[] POPUP_PATH = new string[] { ACTION_NAME };

	public EditBitFieldAction(CompositeEditorProvider<object,object> provider) : base(provider, ACTION_NAME, GROUP_NAME, POPUP_PATH, null, null)
    {
		setDescription(DESCRIPTION);
		if (!(model is CompEditorModel)) {
			throw new AssertException("unsupported use");
		}
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {
		StructureEditorProvider structProvider = (StructureEditorProvider) provider;
		structProvider.showBitFieldEditor();
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		return !hasIncompleteFieldEntry() &&
			(provider is StructureEditorProvider structProvider) &&
			structProvider.getSelectedNonPackedBitFieldComponent() != null;
	}
}
